#include <SPI.h>
#include <Adafruit_GFX.h>

// XIAO ESP32S3のピン配置定義
#define TFT_MOSI 10  // D10
#define TFT_SCLK 8   // D8
#define TFT_CS   4   // D3
#define TFT_DC   3   // D2
#define TFT_RST  2   // D1

// ST7735のコマンド定義
#define ST7735_SWRESET 0x01
#define ST7735_SLPOUT  0x11
#define ST7735_FRMCTR1 0xB1
#define ST7735_DISPON  0x29
#define ST7735_CASET   0x2A
#define ST7735_RASET   0x2B
#define ST7735_RAMWR   0x2C
#define ST7735_MADCTL  0x36
#define ST7735_COLMOD  0x3A

// Adafruit_GFXを継承して最小限の描画クラスを作成
class MinimalST7735 : public Adafruit_GFX {
public:
  MinimalST7735() : Adafruit_GFX(160, 128) {} // 横向き(160x128)として初期化

  void begin() {
    pinMode(TFT_CS, OUTPUT);
    pinMode(TFT_DC, OUTPUT);
    pinMode(TFT_RST, OUTPUT);

    digitalWrite(TFT_CS, HIGH);

    // ハードウェアSPIの開始
    SPI.begin(TFT_SCLK, -1, TFT_MOSI, TFT_CS);
    SPI.setFrequency(24000000); // 24MHz

    // ハードウェアリセット
    digitalWrite(TFT_RST, HIGH); delay(50);
    digitalWrite(TFT_RST, LOW);  delay(50);
    digitalWrite(TFT_RST, HIGH); delay(150);

    // 液晶初期化コマンド送信
    writeCommand(ST7735_SWRESET); delay(150);
    writeCommand(ST7735_SLPOUT);  delay(500);

    writeCommand(ST7735_COLMOD);
    writeData(0x05); // 16-bit color

    writeCommand(ST7735_MADCTL);
    writeData(0xA8); // 画面の向き・色の並び(BGR)を設定

    writeCommand(ST7735_DISPON);  delay(100);
  }

  // Adafruit_GFXが画面にドットを描画するために必須の関数
  void drawPixel(int16_t x, int16_t y, uint16_t color) override {
    if ((x < 0) || (x >= _width) || (y < 0) || (y >= _height)) return;
    setWindow(x, y, x, y);
    writeData(color >> 8);
    writeData(color & 0xFF);
  }

  // 画面塗りつぶし（高速化用）
  void fillScreen(uint16_t color) override {
    setWindow(0, 0, _width - 1, _height - 1);
    digitalWrite(TFT_DC, HIGH);
    digitalWrite(TFT_CS, LOW);
    for (uint32_t i = 0; i < (uint32_t)_width * _height; i++) {
      SPI.transfer(color >> 8);
      SPI.transfer(color & 0xFF);
    }
    digitalWrite(TFT_CS, HIGH);
  }

private:
  void writeCommand(uint8_t cmd) {
    digitalWrite(TFT_DC, LOW);
    digitalWrite(TFT_CS, LOW);
    SPI.transfer(cmd);
    digitalWrite(TFT_CS, HIGH);
  }

  void writeData(uint8_t data) {
    digitalWrite(TFT_DC, HIGH);
    digitalWrite(TFT_CS, LOW);
    SPI.transfer(data);
    digitalWrite(TFT_CS, HIGH);
  }

  void setWindow(uint8_t x0, uint8_t y0, uint8_t x1, uint8_t y1) {
    writeCommand(ST7735_CASET);
    writeData(0x00); writeData(x0 + 0); // オフセット調整が必要な場合は+0を変更
    writeData(0x00); writeData(x1 + 0);

    writeCommand(ST7735_RASET);
    writeData(0x00); writeData(y0 + 0);
    writeData(0x00); writeData(y1 + 0);

    writeCommand(ST7735_RAMWR);
  }
};

// インスタンスを作成
MinimalST7735 tft;

void setup() {
  Serial.begin(115200);

  // 液晶の初期化
  tft.begin();

  // 画面を黒色でクリア
  tft.fillScreen(0x0000); // 黒

  // Adafruit_GFXの標準機能でテキストを描画
  tft.setCursor(10, 20);
  tft.setTextColor(0xFFFF); // 白
  tft.setTextSize(2);
  tft.println("XIAO ESP32S3");

  tft.setCursor(10, 50);
  tft.setTextColor(0x07E0); // 緑
  tft.println("GFX ONLY TEST");

  // グラフィックの描画テスト（青い矩形）
  tft.drawRect(5, 5, 150, 118, 0x001F); // 青
}

void loop() {
  // 動作確認用のループ処理
  tft.setCursor(10, 80);
  tft.setTextColor(0xF800, 0x0000); // 赤（背景黒）
  tft.print("RUNNING... ");
  delay(500);

  tft.setCursor(10, 80);
  tft.setTextColor(0xFFE0, 0x0000); // 黄（背景黒）
  tft.print("RUNNING...*");
  delay(500);
}
